// Real Uttar Pradesh Election Police Standards, Norms, Instructions & Directory
// Extracted from official Lok Sabha Election 2024 records (Distt Ayodhya)

export const ELECTION_DUTY_CARD_INSTRUCTIONS = [
  "1. प्रत्येक पुलिस कर्मी अच्छी वर्दी पहने, अनुशासित रहे। समय की पाबन्दी रखें।",
  "2. कर्तव्यपालन के दौरान हर कार्यवाही दृढ़ता, शालीनता एवं निष्पक्षतापूर्वक करें, किसी के साथ दुर्व्यवहार न किया जाये।",
  "3. ड्यूटी प्रत्येक चरण में पृथक-पृथक तिथियों में हो सकती है। अतः सभी चरणों की ड्यूटी को भली-भाँति समझ कर कार्यवाही करें।",
  "4. ड्यूटी पर जाने से पहले अपने ड्यूटी कार्ड को भली-भाँति समझ लें, यदि संदेह हो तो सक्षम अधिकारी से समाधान करा लें।",
  "5. जनपद के सभी वरिष्ठ अधिकारियों/जोनल/सेक्टर आफिसर तथा जनपद कन्ट्रोल रूम के टेलीफोन नम्बर अवश्य रखें।",
  "6. चुनाव में ऐसा व्यवहार/वार्तालाप कदापि न करें, जिससे किसी पार्टी के पक्ष अथवा विपक्ष में विचारधारा परिलक्षित होती हो।",
  "7. किसी भी उम्मीदवार/एजेन्ट अथवा राजनीति से सम्बन्धित व्यक्ति द्वारा किसी प्रकार सुविधा अथवा सामग्री ग्रहण न करें।",
  "8. यदि पोलिंग बूथ पर ड्यूटी है तो बिना पीठासीन अधिकारी की अनुमति के जब तक शान्ति व्यवस्था हेतु न बुलाया जाये, बूथ में प्रवेश न करें।",
  "9. ई०वी०एम० को अपने कब्जे में न लें, पीठासीन अधिकारी को उसकी सुरक्षा हेतु सहयोग करें।",
  "10. किसी प्रकार का हथियार, लाठी, डण्डा, मोबाईल फोन, वाहन या कोई आपत्तिजनक सामग्री को लेकर कोई व्यक्ति मतदान केन्द्र या चारों ओर निर्धारित सीमा के अन्दर न जा सके।",
  "11. पोलिंग बूथ के 200 मीटर परिधि क्षेत्र के अन्दर किसी प्रकार की दुकानें आदि न लगने दें ताकि असामाजिक तत्वों को इकट्ठा होने का मौका न मिले।",
  "12. पूर्ण निष्पक्षता के साथ कार्यवाही करें तथा किसी को मतदान करने/न करने हेतु प्रेरित अथवा प्रभावित करने की कार्यवाही न करें।",
  "13. किसी भी प्रकार के मादक पदार्थों का सेवन कदापि न करें।",
  "14. यह सुनिश्चित करें कि मतदाता बूथ पर एक लाइन में रहें, वहाँ भीड़-भाड़ न एकत्र हो।",
  "15. अपनी पानी की बोतल साथ रखें, अशुद्ध पदार्थ आदि न खायें, गर्मी/लू आदि से बचाव हेतु सावधानी रखें।",
  "16. बूथ पर महिलाओं की लाइन महिला पुलिस/महिला होमगार्ड्स से ही लगवाना सुनिश्चित करें।"
];

